import React, { useState, useEffect } from 'react';
import './App.css'; // ⚠️ BU SATIR OLMAZSA TASARIM ÇALIŞMAZ!

function App() {
  const [mekanlar, setMekanlar] = useState([]);
  const [favoriler, setFavoriler] = useState([]); 
  const [filtre, setFiltre] = useState('Hepsi');
  const [maxSure, setMaxSure] = useState('');

  useEffect(() => {
    fetch('http://localhost:5000/api/rota')
      .then(res => res.json())
      .then(data => setMekanlar(Array.isArray(data) ? data : []))
      .catch(err => console.error("Bağlantı Hatası:", err));
  }, []);

  const favoriEkleCikar = (mekan) => {
    setFavoriler((prev) => {
      const aktifListe = Array.isArray(prev) ? prev : [];
      const varMi = aktifListe.some(f => f.id === mekan.id);
      return varMi 
        ? aktifListe.filter(f => f.id !== mekan.id)
        : [...aktifListe, { ...mekan, sure: Number(mekan.sure) || 0 }];
    });
  };

  const toplamSure = (favoriler || []).reduce((toplam, m) => toplam + (Number(m.sure) || 0), 0);

  const getKategoriRenk = (kat) => {
    switch(kat) {
      case 'Tarih': return '#d35400';
      case 'Doğa': return '#27ae60';
      case 'Yemek': return '#c0392b';
      case 'Eğlence': return '#8e44ad';
      default: return '#3498db';
    }
  };

  const filtrelenmis = mekanlar.filter(m => {
    const katUygun = filtre === 'Hepsi' || m.kategori === filtre;
    const sureUygun = maxSure === '' || (Number(m.sure) || 0) <= Number(maxSure);
    return katUygun && sureUygun;
  });

  return (
    <div className="container">
      <div className="header">
        <h1>🌴 Antalya Rota Asistanı</h1>
      </div>

      <div className="controls">
        <input type="number" className="search-input" placeholder="Maks. Süre (dk)" 
          value={maxSure} onChange={(e) => setMaxSure(e.target.value)} />
        {['Hepsi', 'Tarih', 'Doğa', 'Yemek', 'Eğlence'].map(k => (
          <button key={k} className={`filter-btn ${filtre === k ? 'active' : ''}`} onClick={() => setFiltre(k)}>{k}</button>
        ))}
      </div>

      <div className="summary-bar">
        <span>Seçilen: {favoriler.length} Mekan</span>
        <span>Toplam: {Math.floor(toplamSure / 60)}sa {toplamSure % 60}dk</span>
      </div>

      <div className="grid">
        {filtrelenmis.map(m => {
          const seciliMi = favoriler?.some(f => f.id === m.id);
          return (
            <div key={m.id} className="card" onClick={() => favoriEkleCikar(m)}>
              <div className="card-image-container">
                <img src={m.resim} alt={m.ad} className="card-img" />
                <span className="badge" style={{ backgroundColor: getKategoriRenk(m.kategori) }}>{m.kategori}</span>
              </div>
              <div className="card-content">
                <h3 className="card-title">{m.ad}</h3>
                <div className="card-info">
                   <span>📍 {m.bolge}</span>
                   <span>⏳ {m.sure} dk</span>
                </div>
                <button className={`btn-action ${seciliMi ? 'btn-remove' : 'btn-add'}`}>
                  {seciliMi ? 'Çıkar' : 'Ekle'}
                </button>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

export default App;
